css:
    body {
        font-family: Arial, Helvetica, sans-serif;
        font-size: 10px;
        color: #222;
    }

    .header-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 8px;
    }

    .header-table td {
        border: 1px solid #555;
        padding: 5px;
        vertical-align: middle;
    }

    .logo-cell {
        width: 20%;
        text-align: center;
    }

    .company-logo {
        max-width: 150px;
        max-height: 65px;
    }

    .title-cell {
        width: 50%;
        text-align: center;
    }

    .order-title {
        font-size: 18px;
        font-weight: bold;
        text-transform: uppercase;
    }

    .order-company {
        font-size: 11px;
        font-weight: bold;
        margin-top: 4px;
    }

    .meta-cell {
        width: 30%;
        font-size: 9px;
        line-height: 1.6;
    }

    .folio-cell {
        font-size: 10px;
        font-weight: bold;
    }

    .bold {
        font-weight: bold;
    }

    .section-title {
        background-color: #e6e6e6;
        font-weight: bold;
        font-size: 10px;
        text-transform: uppercase;
        padding: 5px !important;
    }

    .info-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 8px;
    }

    .info-table td {
        border: 1px solid #777;
        padding: 5px;
        vertical-align: top;
    }

    .small-text {
        font-size: 9px;
    }

.items-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 5px !important;
        margin-bottom: 5px !important;
        font-size: 9px;
    }

    .items-table th {
        background-color: #e6e6e6 !important;
        border: 1px solid #555 !important;
        /* Forzar padding mínimo en los encabezados (Arriba/Abajo Izquierda/Derecha) */
        padding: 2px 2px !important; 
        text-align: center;
        font-weight: bold;
        line-height: 1.1 !important; /* Reduce el espacio vertical del texto */
    }

    .items-table td {
        border: 1px solid #777 !important;
        /* Forzar padding mínimo en las celdas: 1px arriba/abajo, 2px a los lados */
        padding: 1px 2px !important; 
        vertical-align: middle !important;
        line-height: 1.1 !important; /* Reduce el interlineado dentro de la celda */
    }

    /* Eliminar márgenes de cualquier párrafo o div dentro de la tabla generado por ERPNext */
    .items-table td p, 
    .items-table td div {
        margin: 0 !important;
        padding: 0 !important;
    }

    .text-center {
        text-align: center;
    }

    .text-right {
        text-align: right;
    }

    .totals-table {
        width: 40%;
        margin-left: auto;
        border-collapse: collapse;
        margin-top: 8px;
        font-size: 9px;
    }

    .totals-table td {
        border: 1px solid #777;
        padding: 5px;
    }

    .total-label {
        font-weight: bold;
        text-align: right;
        background-color: #e6e6e6;
    }

    .grand-total {
        font-size: 11px;
        font-weight: bold;
        background-color: #e6e6e6;
    }

    .amount-words {
        border: 1px solid #777;
        padding: 6px;
        margin-top: 8px;
        font-size: 9px;
    }

    .notes-box {
        border: 1px solid #777;
        padding: 6px;
        margin-top: 8px;
        min-height: 35px;
        font-size: 9px;
    }

    .signature-section {
        margin-top: 35px;
    }

    .signature-table {
        width: 100%;
        border-collapse: collapse;
        text-align: center;
    }

    .signature-table td {
        width: 33.33%;
        padding-top: 20px;
    }

    .signature-line {
        border-top: 1px solid #555;
        padding-top: 5px;
        font-size: 9px;
    }

    .footer-order {
        margin-top: 15px;
        padding-top: 6px;
        border-top: 1px solid #777;
        text-align: center;
        font-size: 8px;
        line-height: 1.4;
    }
    .signature-line {
    text-align: center;
    vertical-align: bottom;
    padding-top: 20px;
}

.signature-line img {
    display: block;
    margin: 0 auto 5px auto;
}

.signature-border {
    border-top: 1px solid #000;
    width: 180px;
    margin: 0 auto 4px auto;
}

body{
font-family: Arial, Helvetica, sans-serif;
font-size:12px;
}

table{
width:100%;
border-collapse:collapse;
table-layout:fixed;
}

.header-table td{
border:1px solid #000;
padding:6px;
vertical-align:middle;
}

.logo-cell{
width:20%;
text-align:center;
}

.company-logo{
max-height:80px;
display:block;
margin:auto;
}

.title-cell{
width:55%;
text-align:center;
}

.meta-cell{
width:25%;
font-size:10px;
}

.cert-title{
font-size:16px;
font-weight:bold;
}

.cert-company{
font-size:11px;
}

.section-title{
font-weight:bold;
text-align:center;
background:#f2f2f2;
}

.small-text{
font-size:11px;
}

.intro-text{
text-align:justify;
line-height:1.5;
margin:15px 0;
}

.result-table th{
background:#f3f3f3;
font-weight:bold;
}

.result-ok{
color:#2e7d32;
font-weight:bold;
}

.result-bad{
color:#c62828;
font-weight:bold;
}

.signature-section{
margin-top:60px;
}

.signature-line{
border-top:1px solid #000;
text-align:center;
font-size:11px;
padding-top:6px;
}

.page-number:before{
content:counter(page);
}

.page-count:before{
content:counter(pages);
}

@media print{

thead{
display:table-header-group;
}

tr{
page-break-inside:avoid;
}

}
.footer-certificado{
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    text-align: center;
    font-size: 10px;
    border-top: 1px solid #000;
    padding-top: 5px;
    background: white;
}
